//! Offline tests for the deterministic BASIC fallback program (issue #2075).
//! The generator never returns null and keeps the generated script parseable.

use super::fallback_basic_program;

#[test]
fn the_fallback_emits_a_comment_and_a_talk_statement() {
    let program = fallback_basic_program("daily_sales", "report sales every day");

    assert_eq!(
        program,
        "' daily_sales\n\
         ' Generated by AutoTask (BASIC-only pipeline)\n\
         TALK \"Run daily_sales: report sales every day\"\n"
    );
}

#[test]
fn an_empty_plan_name_falls_back_to_scheduled_task() {
    let program = fallback_basic_program("   ", "do something");

    assert!(program.starts_with("' scheduled_task\n"));
    assert!(program.contains("TALK \"Run scheduled_task: do something\""));
}

#[test]
fn the_plan_name_is_trimmed_and_cut_at_sixty_characters() {
    let name = format!("  {}  ", "n".repeat(80));
    let program = fallback_basic_program(&name, "intent");

    let first_line = program.lines().next().expect("first line");
    assert_eq!(first_line, format!("' {}", "n".repeat(60)));
}

#[test]
fn the_intent_is_cut_at_one_hundred_twenty_characters() {
    let intent = "i".repeat(200);
    let program = fallback_basic_program("plan", &intent);

    assert!(program.contains(&format!("TALK \"Run plan: {}\"", "i".repeat(120))));
}

#[test]
fn quotes_in_the_intent_are_escaped_for_the_basic_literal() {
    let program = fallback_basic_program("plan", "say \"hello\" now");
    assert!(program.contains(r#"say \"hello\" now"#));
    assert_eq!(
        program.lines().last(),
        Some(r#"TALK "Run plan: say \"hello\" now""#)
    );
}

#[test]
fn backslashes_are_escaped_and_the_program_stays_three_lines() {
    let program = fallback_basic_program("plan", "path C:\\tmp\\x");
    assert!(program.contains(r#"C:\\tmp\\x"#));
    assert_eq!(program.lines().count(), 3);
}
